func (this *Btcmarkets) ParseMarket(market any) map[string]any {
	var baseId *string = this.SafeString(market, "baseAssetName")
	var quoteId *string = this.SafeString(market, "quoteAssetName")
	var id *string = this.SafeString(market, "marketId")
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var symbol string = *base + "/" + *quote
	var fees any = this.SafeDict(this.SafeDict(this.Options, "fees", map[string]any{}), quote, this.Fees)
	var pricePrecision *float64 = this.ParseNumber(this.ParsePrecision(this.SafeString(market, "priceDecimals")))
	var minAmount *float64 = this.SafeNumber(market, "minOrderAmount")
	var maxAmount *float64 = this.SafeNumber(market, "maxOrderAmount")
	var status *string = this.SafeString(market, "status")
	var minPrice *float64 = nil
	if quote != nil && *quote == "AUD" {
		minPrice = pricePrecision
	}
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         nil,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"active":         (status != nil && *status == "Online"),
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"taker":          this.SafeNumber(fees, "taker"),
		"maker":          this.SafeNumber(fees, "maker"),
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "amountDecimals"))),
			"price":  pricePrecision,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": minAmount,
				"max": maxAmount,
			},
			"price": map[string]any{
				"min": minPrice,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	})
}

