func (this *Btcmarkets) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// public fetchTrades
	//
	//     {
	//         "id":"6191646611",
	//         "price":"539.98",
	//         "amount":"0.5",
	//         "timestamp":"2020-08-09T15:21:05.016000Z",
	//         "side":"Ask"
	//     }
	//
	// private fetchMyTrades
	//
	//     {
	//         "id": "36014819",
	//         "marketId": "XRP-AUD",
	//         "timestamp": "2019-06-25T16:01:02.977000Z",
	//         "price": "0.67",
	//         "amount": "1.50533262",
	//         "side": "Ask",
	//         "fee": "0.00857285",
	//         "orderId": "3648306",
	//         "liquidityType": "Taker",
	//         "clientOrderId": "48"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.Parse8601(this.SafeString(trade, "timestamp"))
	var marketId *string = this.SafeString(trade, "marketId")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "-")
	var feeCurrencyCode any = nil
	if marketResolved["quote"] == "AUD" {
		feeCurrencyCode = marketResolved["quote"]
	} else {
		feeCurrencyCode = marketResolved["base"]
	}
	var side *string = this.SafeString(trade, "side")
	if side != nil && *side == "Bid" {
		side = SafeStringPtr("buy")
	} else if side != nil && *side == "Ask" {
		side = SafeStringPtr("sell")
	}
	var id *string = this.SafeString(trade, "id")
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = this.SafeString(trade, "amount")
	var orderId *string = this.SafeString(trade, "orderId")
	var fee map[string]any = nil
	var feeCostString *string = this.SafeString(trade, "fee")
	if feeCostString != nil {
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrencyCode,
		}
	}
	var takerOrMaker *string = this.SafeStringLower(trade, "liquidityType")
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        orderId,
		"symbol":       marketResolved["symbol"],
		"type":         nil,
		"side":         side,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"takerOrMaker": takerOrMaker,
		"fee":          fee,
	}, marketResolved)
}

