func (this *Btcmarkets) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"marketId": market["id"],
		"amount":   this.AmountToPrecision(symbol, amount),
		"side": func() string {
			if side == "buy" {
				return "Bid"
			}
			return "Ask"
		}(),
	}
	var lowercaseType string = strings.ToLower(typeVar)
	var orderTypes map[string]any = this.SafeDictMap(this.Options, "orderTypes", map[string]any{
		"limit":       "Limit",
		"market":      "Market",
		"stop":        "Stop",
		"stop limit":  "Stop Limit",
		"take profit": "Take Profit",
	})
	request["type"] = this.SafeString(orderTypes, lowercaseType, typeVar)
	var priceIsRequired bool = false
	var triggerPriceIsRequired bool = false
	if lowercaseType == "limit" {
		priceIsRequired = true
	} else if lowercaseType == "stop limit" {
		triggerPriceIsRequired = true
		priceIsRequired = true
	} else if lowercaseType == "take profit" {
		triggerPriceIsRequired = true
	} else if lowercaseType == "stop" {
		triggerPriceIsRequired = true
	}
	if priceIsRequired {
		if price == nil {
			panic(ArgumentsRequired(this.Id + " createOrder() requires a price argument for a " + typeVar + "order"))
		} else {
			request["price"] = this.PriceToPrecision(symbol, price)
		}
	}
	if triggerPriceIsRequired {
		var triggerPrice *float64 = this.SafeNumber(params, "triggerPrice")
		if triggerPrice == nil {
			panic(ArgumentsRequired(this.Id + " createOrder() requires a triggerPrice parameter for a " + typeVar + "order"))
		} else {
			request["triggerPrice"] = this.PriceToPrecision(symbol, triggerPrice)
		}
	}
	var clientOrderId *string = this.SafeString(params, "clientOrderId")
	if clientOrderId != nil {
		request["clientOrderId"] = clientOrderId
	}
	var paramsTriggerPrice any = params
	if triggerPriceIsRequired {
		paramsTriggerPrice = this.Omit(params, "triggerPrice")
	}
	var paramsOmitted any = this.Omit(paramsTriggerPrice, "clientOrderId")

	r1 := <-this.PrivatePostOrders(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "orderId": "7524",
	//         "marketId": "BTC-AUD",
	//         "side": "Bid",
	//         "type": "Limit",
	//         "creationTime": "2019-08-30T11:08:21.956000Z",
	//         "price": "100.12",
	//         "amount": "1.034",
	//         "openAmount": "1.034",
	//         "status": "Accepted",
	//         "clientOrderId": "1234-5678",
	//         "timeInForce": "IOC",
	//         "postOnly": false,
	//         "selfTrade": "P",
	//         "triggerAmount": "105",
	//         "targetAmount": "1000"
	//     }
	//
	ch <- AsyncResult[Order]{Value: this.ParseOrder(response, market)}
	return nil
}

