func (this *Btcmarkets) CalculateFee(symbol any, typeVar any, side any, amount any, price any, optionalArgs ...any) any {
	/**
	 * @method
	 * @description calculates the presumptive fee that would be charged for an order
	 * @param {string} symbol unified market symbol
	 * @param {string} type not used by btcmarkets.calculateFee
	 * @param {string} side not used by btcmarkets.calculateFee
	 * @param {float} amount how much you want to trade, in units of the base currency on most exchanges, or number of contracts
	 * @param {float} price the price for the order to be filled at, in units of the quote currency
	 * @param {string} takerOrMaker 'taker' or 'maker'
	 * @param {object} params
	 * @returns {object} contains the rate, the percentage multiplied to the order amount to obtain the fee amount, and cost, the total value of the fee in units of the quote currency, for the order
	 */
	var takerOrMaker string = GetArgString(optionalArgs, 0, "taker")
	_ = takerOrMaker
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var market map[string]any = this.Market(symbol)
	var currency *string = nil
	var cost any = nil
	if market["quote"] == "AUD" {
		currency = this.SafeString(market, "quote")
		cost = this.CostToPrecision(symbol, Precise.StringMul(this.NumberToString(amount), this.NumberToString(price)))
	} else {
		currency = this.SafeString(market, "base")
		if derefPtr := this.AmountToPrecision(symbol, amount); derefPtr != nil {
			cost = *derefPtr
		} else {
			cost = nil
		}
	}
	var rate any = this.SafeValue(market, takerOrMaker)
	var rateCost *string = Precise.StringMul(this.NumberToString(rate), cost)
	var feeCost any = this.FeeToPrecision(symbol, rateCost)
	if feeCost == nil {
		feeCost = "0"
	}
	return map[string]any{
		"type":     takerOrMaker,
		"currency": currency,
		"rate":     rate,
		"cost":     this.ParseNumber(feeCost),
	}
}
func (this *Btcmarkets) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"Accepted":            "open",
		"Placed":              "open",
		"Partially Matched":   "open",
		"Fully Matched":       "closed",
		"Cancelled":           "canceled",
		"Partially Cancelled": "canceled",
		"Failed":              "rejected",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Btcmarkets) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// createOrder
	//
	//     {
	//         "orderId": "7524",
	//         "marketId": "BTC-AUD",
	//         "side": "Bid",
	//         "type": "Limit",
	//         "creationTime": "2019-08-30T11:08:21.956000Z",
	//         "price": "100.12",
	//         "amount": "1.034",
	//         "openAmount": "1.034",
	//         "status": "Accepted",
	//         "clientOrderId": "1234-5678",
	//         "timeInForce": "IOC",
	//         "postOnly": false,
	//         "selfTrade": "P",
	//         "triggerAmount": "105",
	//         "targetAmount": "1000"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.Parse8601(this.SafeString(order, "creationTime"))
	var marketId *string = this.SafeString(order, "marketId")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "-")
	var side *string = this.SafeString(order, "side")
	if side != nil && *side == "Bid" {
		side = SafeStringPtr("buy")
	} else if side != nil && *side == "Ask" {
		side = SafeStringPtr("sell")
	}
	var typeVar *string = this.SafeStringLower(order, "type")
	var price *string = this.SafeString(order, "price")
	var amount *string = this.SafeString(order, "amount")
	var remaining *string = this.SafeString(order, "openAmount")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var id *string = this.SafeString(order, "orderId")
	var clientOrderId *string = this.SafeString(order, "clientOrderId")
	var timeInForce *string = this.SafeString(order, "timeInForce")
	var postOnly *bool = this.SafeBool(order, "postOnly")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             marketResolved["symbol"],
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"side":               side,
		"price":              price,
		"triggerPrice":       this.SafeNumber(order, "triggerPrice"),
		"cost":               nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          remaining,
		"average":            nil,
		"status":             status,
		"trades":             nil,
		"fee":                nil,
	}, marketResolved)
}

